BEGIN
--------------------------------------------------------------------------
--Query to populate S3 rtx layer based on hash key not present in s2.
-----------------------------------------------------------------------------	
	insert into `bidata-sharedus-production.S3.rtx_lead_source_system_tracker` (
		SELECT a.* FROM `bidata-sharedus-production.S2.rtx_lead_source_system_tracker` A LEFT OUTER JOIN
		`bidata-sharedus-production.S3.rtx_lead_source_system_tracker` B ON  A.hashdiff = B.hashdiff  
		where A.cre_date >= TIMESTAMP(current_date()) and B.hashdiff is null
	);

	insert into `bidata-sharedus-production.S3.rtx_lead_uid_association` (
		SELECT a.* FROM `bidata-sharedus-production.S2.rtx_lead_uid_association` A LEFT OUTER JOIN
		`bidata-sharedus-production.S3.rtx_lead_uid_association` B ON  A.hashdiff = B.hashdiff  
		where A.cre_date >= TIMESTAMP(current_date()) and B.hashdiff is null
	);	

	insert into `bidata-sharedus-production.S3.rtx_lead` (
		SELECT a.* FROM `bidata-sharedus-production.S2.rtx_lead` A LEFT OUTER JOIN
