BEGIN	                                                       
	 DECLARE pVersionNumber STRING;
	 DECLARE pSrctableName STRING; 
	 DECLARE pSrcColumns STRING;
	 DECLARE pPrimaryKey STRING;
   DECLARE pTrgtschemaname STRING;
	 DECLARE pTrgttablename STRING; 
	 DECLARE pTargetKeyColumn STRING;
	 DECLARE pLoadpattern STRING;
	 DECLARE pSrccastColumns STRING; 
   DECLARE pStgColumns  STRING; 
	 DECLARE pTargetType STRING;
   DECLARE psrcdataset STRING;
   DECLARE pAudit STRING;
   DECLARE pConfig STRING;
   DECLARE pQuery STRING;
   DECLARE sql STRING;
   SET pAudit=CONCAT(pDataset, '.', pAuditTable);
   SET pConfig=CONCAT(pDataset, '.', pConfigTable);
   


    SET sql = FORMAT("""
        SELECT versionnumber,srctablename,srccolumns,primarykey,targetschema,trgttablename,tgtkeycolumn,loadpattern,srcastccolumns,targettype,stgcolumns,srctabledatabase
        FROM `%s`
        WHERE LOWER(entityname) = lower(@entityName)
    """, pConfig);

    -- Execute the dynamic SQL
    EXECUTE IMMEDIATE sql USING pentityname AS entityName;

    -- Assign the results to the declared variables
    EXECUTE IMMEDIATE sql INTO pVersionNumber,pSrctableName,pSrcColumns,pPrimaryKey,pTrgtschemaname,pTrgttablename,pTargetKeyColumn,pLoadpattern,pSrccastColumns,pTargetType,pStgColumns,psrcdataset USING pentityname AS entityName;


   SET pQuery='INSERT INTO '||pAudit||' (select jobid,"SP_ndp_ingest",loadtype,srcobjectname,versionnumber,incrementalstarttimestamp,incrementalendtimestamp,tgtobjectname,srctype,srccount,tgtcount,"Complete",object,jobname,CURRENT_TIMESTAMP() from '||pAudit||' where status='||"'"||'Complete'||"'"||' and jobid='||pjobid||' and object='||"'"||pentityname||"'"||')';
   
  select pQuery;
  	  
            IF(lower(pLoadpattern)='insert')
              THEN 
                    EXECUTE IMMEDIATE 
                    'INSERT INTO ' ||pTrgtschemaname||'.'|| pTrgttablename || '(' || pStgColumns || ')(Select ' || pSrcCastColumns || ' from '||psrcdataset||'.ext_'|| pTrgttablename||' where _FILE_NAME LIKE '||"'%" ||pjobid||"%'" || ')';                            
                     SELECT @@row_count;
                     
                     
                     EXECUTE IMMEDIATE pQuery;

                     SELECT @@row_count;
              
            ELSEIF(lower(pLoadpattern)= 'truncload') 
            THEN 
              EXECUTE IMMEDIATE 
                  'DELETE from '||pTrgtschemaname||'.'||pTrgttablename||' where 1=1';
              EXECUTE IMMEDIATE 
                  'INSERT INTO ' || pTrgtschemaname||'.'||pTrgttablename || '(' || pStgColumns || ')(Select ' || pSrcCastColumns || ' from '||psrcdataset||'.ext_' || pTrgttablename||' where _FILE_NAME LIKE '||"'%" ||pjobid||"%'" || ')';       
                 SELECT @@row_count;
                  
                 
                 EXECUTE IMMEDIATE pQuery;
                    
                  SELECT @@row_count;

            ELSEIF(lower(pLoadpattern)= 'upsert') 
            THEN 

                EXECUTE IMMEDIATE 'delete from '|| pTrgtschemaname||'.'||pTrgttablename ||' a where EXISTS (Select 1 from '||psrcdataset||'.ext_' ||pTrgttablename||' b where b'||'.'||pPrimaryKey||'='||'a'||'.'||pTargetKeyColumn|| ' and  _FILE_NAME LIKE '||"'%" ||pjobid||"%'"||')';
    
                EXECUTE IMMEDIATE 'INSERT INTO '|| pTrgtschemaname||'.'||pTrgttablename ||'('|| pStgColumns ||')(Select ' || pSrcCastColumns || ' from '||psrcdataset||'.ext_' || pTrgttablename||' where _FILE_NAME LIKE '||"'%" ||pjobid||"%'" || ')';     
    
                 SELECT @@row_count;
                 
                 EXECUTE IMMEDIATE pQuery;

                 SELECT @@row_count;

            ELSEIF(lower(pLoadpattern)= 'splupsert') 
           THEN 

           EXECUTE IMMEDIATE 'CREATE OR REPLACE TABLE '|| pTrgtschemaname||'.'||pTrgttablename ||'_TMP AS'||'(Select ' || pSrcCastColumns || ',to_hex(sha1('||pPrimaryKey||')) as hashkey from '||psrcdataset||'.ext_' || pTrgttablename||' where _FILE_NAME LIKE '||"'%" ||pjobid||"%'" || ')';   
           SELECT @@row_count;  
                
            EXECUTE IMMEDIATE 'delete from '||  pTrgtschemaname||'.'|| pTrgttablename ||' a where EXISTS (Select 1 from '||pTrgtschemaname||'.' || pTrgttablename||'_TMP b where b.hashkey= a.'||pTargetKeyColumn || ')';
            SELECT @@row_count;

                EXECUTE IMMEDIATE 'INSERT INTO ' || pTrgtschemaname||'.'||pTrgttablename || '(' || pStgColumns ||',hashkey)(Select ' || pSrcCastColumns || ',hashkey from '||pTrgtschemaname||'.'||pTrgttablename ||'_TMP'||')';   
                SELECT @@row_count;    

                 EXECUTE IMMEDIATE 'DROP TABLE '|| pTrgtschemaname||'.'||pTrgttablename ||'_TMP';   
                 SELECT @@row_count;
                 
                 EXECUTE IMMEDIATE pQuery;
                 SELECT @@row_count;

            END IF;
  EXCEPTION
  WHEN ERROR THEN
  BEGIN
    DECLARE pAudit STRING;
    SET pAudit=CONCAT(pDataset, '.', pAuditTable);

      SELECT @@error.message;
      IF (@@error.message like '%error%')
      THEN
       EXECUTE IMMEDIATE 'INSERT INTO '||pAudit||' (select jobid,"SP_ndp_ingest",loadtype,srcobjectname,versionnumber,incrementalstarttimestamp,incrementalendtimestamp,tgtobjectname,srctype,srccount,tgtcount,"Error",object,jobname,CURRENT_TIMESTAMP() from '||pAudit||' where status='||"'"||'Complete'||"'"||' and jobid='||pjobid||' and object='||"'"||pentityname||"'"||')';

      END IF;
    END;

END

BEGIN
  -- Declare variables
  DECLARE dataset, sourcetablename, incrementalkey, tableNameWithZeroCount STRING;
  DECLARE tableCount INT64;

  -- Iterate over the tables and insert row counts into Results
  FOR row IN (
    SELECT dataset, sourcetablename, incrementalkey
    FROM `S0_TMX.Legacy_Source_table_info`
  ) DO
    SET dataset = row.dataset;
    SET sourcetablename = row.sourcetablename;
    SET incrementalkey = row.incrementalkey;

    -- Check if the table exists (S0_TMX dataset)
    SET tableCount = (
      SELECT COUNT(1) FROM (
        SELECT table_name FROM S0_TMX.INFORMATION_SCHEMA.TABLES 
        UNION DISTINCT
        SELECT table_name FROM S0.INFORMATION_SCHEMA.TABLES 
      ) WHERE table_name = REGEXP_EXTRACT(sourcetablename, r'([^\.]+$)')
    );

    IF tableCount > 0 THEN
      IF incrementalkey IS NULL OR incrementalkey = '' THEN
        EXECUTE IMMEDIATE FORMAT("""
          INSERT INTO `S0_TMX.Results` (TableName, RowCnt, Date)
          SELECT '%s', COUNT(*), CURRENT_DATE()
          FROM `%s.%s`
        """, sourcetablename, dataset, sourcetablename);
      ELSE
        EXECUTE IMMEDIATE FORMAT("""
          INSERT INTO `S0_TMX.Results` (TableName, RowCnt, Date)
          SELECT '%s', COUNT(*), CURRENT_DATE()
          FROM `%s.%s`
          WHERE DATE(%s) >= DATE_SUB(CAST(TIMESTAMP_TRUNC(CURRENT_TIMESTAMP(), MONTH)AS DATE),INTERVAL 6 MONTH)
        """, sourcetablename, dataset, sourcetablename, incrementalkey);
      END IF;
    END IF;
  END FOR;

END

BEGIN
	 	                                                       
	 DECLARE pVersionNumber STRING;
	 DECLARE pSrctableName STRING; 
