	 DECLARE pTargetType STRING;
	 DECLARE pStgTableSchema String;
   DECLARE pStgSchema STRING;
   DECLARE TgtRowCOunt INT64;
  
	 
	 SET (pVersionNumber,pSrctableName,pSrcColumns,pPrimaryKey,pTrgttablename,pTargetKeyColumn,pLoadpattern,pStgSchema,pSrccastColumns,pTargetType,pStgTableSchema) = (
	 Select as struct versionnumber,srctablename,srccolumns,primarykey,(targetschema||'.'||trgttablename),tgtkeycolumn,loadpattern,'bidata-sharedus-production.stg_tmx',srcastccolumns,targettype,stgTableSchema from bidata-sharedus-production.S0_TMX.rspr_ingestconfig where lower(entityname) = lower(pEntityName)
	 );
  	
            IF(lower(pTargetType)!='postgres')
              THEN 
              
              EXECUTE IMMEDIATE 'DELETE from '||pStgSchema||'.stg_'||pEntityName||' where 1=1';
               EXECUTE IMMEDIATE
                 ' LOAD DATA INTO '||pStgSchema||'.stg_'||pEntityName||'('||pstgTableSchema||')'||
                 'FROM FILES ('||
                 'null_marker=NULL ,'||
                 'allow_quoted_newlines=TRUE,'||
                 'format = "CSV",' ||
                 'skip_leading_rows = 0,'||
                 'uris = '||'["'||psourcepath||'"])';
            END IF ;

             
            IF(lower(pLoadpattern)='insert')
              THEN 
                    EXECUTE IMMEDIATE 
                    'INSERT INTO ' || pTrgttablename || '(' || pSrcColumns || ')(Select ' || pSrcCastColumns || ' from '||pStgSchema||'.stg_' || pEntityName ||')';                            
                     SELECT @@row_count;
              
           ELSEIF(lower(pLoadpattern)= 'truncload') 
           THEN 
              EXECUTE IMMEDIATE 
                  'DELETE from '||pTrgttablename||' where 1=1';
--- /*adding table refresh timestamp for rnaEmployeeTable---/*  
              IF((lower(pEntityName)='vwrnaemployees')) 
              THEN 
                EXECUTE IMMEDIATE 
                  'INSERT INTO ' || pTrgttablename || '(' || pSrcColumns || ',gcp_updated)(Select ' || pSrcCastColumns ||',cast(current_timestamp() as string) from '||pStgSchema||'.stg_' || pEntityName ||')';
              ELSE  
                EXECUTE IMMEDIATE 
                  'INSERT INTO ' || pTrgttablename || '(' || pSrcColumns || ')(Select ' || pSrcCastColumns || ' from '||pStgSchema||'.stg_' || pEntityName ||')';   
                END IF;     
                 SELECT @@row_count;
         
            ELSEIF(lower(pLoadpattern)= 'upsert') 
           THEN 
       
                /*EXECUTE IMMEDIATE 'delete from '|| pTrgttablename ||' using '||pStgSchema||'.stg_'||pEntityName ||' where '||pStgSchema||'.stg_'||pEntityName ||'.'||pPrimaryKey||'='|| pTrgttablename ||'.'||pTargetKeyColumn;*/

                EXECUTE IMMEDIATE 'delete from '|| pTrgttablename ||' a where EXISTS (Select 1 from '||pStgSchema||'.stg_'||pEntityName ||' b where b'||'.'||pPrimaryKey||'='||'cast(a'||'.'||pTargetKeyColumn||' as STRING))';
    
                EXECUTE IMMEDIATE 'INSERT INTO '|| pTrgttablename ||'('|| pSrcColumns ||')(Select ' || pSrcCastColumns || ' from '||pStgSchema||'.stg_' || pEntityName ||')';     
    
                 SELECT @@row_count;
                    
            ELSEIF(lower(pLoadpattern)= 'splupsert') 
           THEN 
                EXECUTE IMMEDIATE 'UPDATE '||pStgSchema||'.stg_'||pEntityName ||' set hashkey=to_hex(sha1('||pPrimaryKey||')) WHERE hashkey is NULL';
                /*EXECUTE IMMEDIATE 'DELETE from '|| pTrgttablename ||' using '||pStgSchema||'.stg_'||pEntityName ||'  where  '||pStgSchema||'.stg_'||pEntityName ||'.hashkey='|| pTrgttablename ||'.'||pTargetKeyColumn;*/

                EXECUTE IMMEDIATE 'delete from '|| pTrgttablename ||' a where EXISTS (Select 1 from '||pStgSchema||'.stg_'||pEntityName ||' b where b'||'.hashkey='||'cast(a'||'.'||pTargetKeyColumn||' as STRING))';

                EXECUTE IMMEDIATE 'INSERT INTO ' || pTrgttablename || '(' || pSrcColumns ||',hashkey)(Select ' || pSrcCastColumns || ',hashkey from '||pStgSchema||'.stg_' || pEntityName ||')';         
                 SELECT @@row_count;
         END IF;    


EXCEPTION
  WHEN ERROR THEN
 SELECT @@error.message;
  --,pTrgttablename,pSrctableName,pIncrementalStartTimestamp,pIncrementalEndTimestamp,pVersionNumber,psourcetype;
              
END

